export const notes=[
 "تاريخي: الخنساء هي تُماضر بنت عمرو بن الحارث بن الشريد، من بني سُليم، شاعرةٌ مخضرمة أدركت الجاهلية والإسلام، وأخبارها في الأغاني والشعر والشعراء وزهر الآداب والعقد الفريد والاستيعاب.",
 "تاريخي: معاوية أخوها لأبيها وأمّها، وصخر أخوها لأبيها. قُتل معاوية في غزوةٍ على بني مرّة، قتله هاشم بن حرملة، وأخذ صخرٌ بثأره، وأبى أن يهجو قاتليه.",
 "تاريخي: خطبها دريد بن الصمّة بعد أن رآها تهنأ بعيرًا، فردّته، وقالت فيه «معاذ الله ينكحني حبركى». وقُتل دريد يوم حنين على يد ربيعة بن رفيع السُّلمي.",
 "تاريخي: شاطرها صخر ماله حين أضاعه زوجها في الميسر، مرةً بعد مرة، وقال رجزه «والله لا أمنحها شرارها». والرواة يختلفون في اسم الزوج.",
 "تاريخي: طُعن صخر في غزوٍ على بني أسد، طعنه ربيعة بن ثور الأسدي، فمرض حولًا، وقالت زوجته سليمى «لا هو حيّ فيُرجى ولا ميّت فيُنعى»، فقال أبياته «أرى أمّ صخرٍ لا تملّ عيادتي». ثم نتأت قطعةٌ من جنبه فقطعوها فمات، ودُفن قرب عسيب.",
 "يُروى: أن صخرًا مدّ يده إلى السيف ليضرب سليمى فلم يقوَ عليه. والقدح المكسور، والكاهنة وسجعها، وعصابة الخمار على الرمح، من خيال القصة.",
 "تاريخي: إنشادها النابغة الذبياني في قبّته الحمراء بعكاظ بعد الأعشى، وقوله «لولا أن أبا بصير أنشدني آنفًا لقلتُ إنكِ أشعر الجنّ والإنس»، وغضب حسّان بن ثابت.",
 "يُروى: نقد بيت حسّان «لنا الجفنات الغرّ» (جمع القلّة، الضحى والدجى، يقطرن ويجرين) يُنسب في الأشهر إلى النابغة، وفي رواياتٍ متأخرة إلى الخنساء. القصة تجعله على لسانها، وتنبّه على ذلك.",
 "تاريخي: قدومها على النبيّ مع قومها من بني سُليم وإسلامها، وأنه كان يستنشدها ويقول «هيهِ يا خناس». ولا تصوّر القصة النبيّ ولا الصحابة ولا أمّهات المؤمنين، وتكتفي بالرواية.",
 "تاريخي: سؤال عمر «ما أقرح مآقي عينيك؟» وجوابها «بكائي على السادات من مضر… ذاك أطول لعويلي عليهم» في زهر الآداب، وخبر الصدار مع عائشة في العقد الفريد.",
 "يُروى: وصيّتها لبنيها الأربعة ليلة القادسية، واستشهادهم، وقولها «الحمد لله الذي شرّفني بقتلهم»، وأن عمر كان يعطيها أرزاقهم. والخبر في الاستيعاب وغيره، ويشكّ فيه بعض المحقّقين، ولا تتّفق المصادر على أسماء البنين.",
 "متخيَّل: الجارة، والضيوف الأسديون، والتاجر المكّي في عكاظ، ولقاء دريد في عكاظ، ولقاء حسّان شيخًا في المدينة، وكل حوارٍ لا تنقله المصادر. والأبيات كلها أصيلة، ولكل بيتٍ مصدران على الأقل."
];
